import java.util.HashMap;
import java.util.concurrent.locks.ReentrantLock;

public class LRUCache<K, V> {
    // Private doubly-linked list node
    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

    private final int capacity;
    private final HashMap<K, Node<K, V>> map;
    // Dummy sentinels — simplify insert/remove (no null checks)
    private final Node<K, V> head = new Node<>(null, null);
    private final Node<K, V> tail = new Node<>(null, null);
    private final ReentrantLock lock = new ReentrantLock();

    public LRUCache(int capacity) {
        if (capacity <= 0)
            throw new IllegalArgumentException("Capacity must be positive");
        this.capacity = capacity;
        this.map = new HashMap<>();
        // Sentinel wiring: head ↔ tail (empty list state)
        head.next = tail;
        tail.prev = head;
    }

    // ── get ────────────────────────────
    public V get(K key) {
        lock.lock();
        try {
            Node<K, V> node = map.get(key);
            if (node == null) return null;  // cache miss

            // Move to front — mark as most recently used
            removeNode(node);
            addToFront(node);
            return node.value;
        } finally {
            lock.unlock();
        }
    }

    // ── put ────────────────────────────
    public void put(K key, V value) {
        if (key == null) throw new NullPointerException("key");
        if (value == null) throw new NullPointerException("value");

        lock.lock();
        try {
            Node<K, V> existing = map.get(key);

            if (existing != null) {
                // Update in place — move to front
                existing.value = value;
                removeNode(existing);
                addToFront(existing);
                return;
            }

            // New entry — evict if at capacity
            if (map.size() == capacity) {
                // Evict the LRU entry (the node right before tail)
                Node<K, V> lru = tail.prev;
                removeNode(lru);
                map.remove(lru.key);
            }

            Node<K, V> newNode = new Node<>(key, value);
            addToFront(newNode);
            map.put(key, newNode);
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return map.size();
        } finally {
            lock.unlock();
        }
    }

    public boolean containsKey(K key) {
        lock.lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.unlock();
        }
    }

    // ── Doubly-linked list helpers ────────
    // Assumptions: sentinels are never removed; we always operate on real nodes.

    // Insert right after head (becomes the new most-recently-used)
    private void addToFront(Node<K, V> node) {
        node.prev = head;
        node.next = head.next;
        head.next.prev = node;
        head.next = node;
    }

    // Unlink from current position in the list
    private void removeNode(Node<K, V> node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
        // Optional: null out prev/next on the removed node to help GC
        // node.prev = null;
        // node.next = null;
    }
}

LRUCache<Integer, String> cache = new LRUCache<>(3);

cache.put(1, "one");      // list: 1
cache.put(2, "two");      // list: 2 -> 1
cache.put(3, "three");    // list: 3 -> 2 -> 1
cache.get(1);             // list: 1 -> 3 -> 2 (1 moved to front)
cache.put(4, "four");     // list: 4 -> 1 -> 3 (2 evicted)
cache.get(2);             // returns null (evicted)
cache.get(3);             // list: 3 -> 4 -> 1
cache.put(1, "ONE!");     // list: 1 -> 3 -> 4 (update + move to front)

System.out.println(cache.size()); // 3
System.out.println(cache.get(1)); // "ONE!"

// Multi-threaded demo: 10 threads hammering the cache
ExecutorService pool = Executors.newFixedThreadPool(10);
for (int t = 0; t < 10; t++) {
    final int tid = t;
    pool.submit(() -> {
        for (int i = 0; i < 1000; i++) {
            cache.put(tid * 1000 + i, "val-" + i);
            cache.get(tid * 1000 + (i - 1));
        }
    });
}
pool.shutdown();
// Invariant: cache.size() <= capacity always holds.

import java.util.LinkedHashMap;
import java.util.Map;

// One-liner LRU cache — not thread-safe as written
class LinkedHashMapLRU<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    public LinkedHashMapLRU(int capacity) {
        // initial capacity, load factor, accessOrder=true → LRU behavior
        super(capacity, 0.75f, true);
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;
    }
}

